```typescript
import { test, expect } from '@playwright/test';

test.describe('Payment Processing Loading State', () => {
  let page;

  test.beforeEach(async ({ browser }) => {
    page = await browser.newPage();
    await page.goto('http://localhost:3000/payment');
    await page.waitForLoadState('networkidle');
  });

  test('should display loading spinner when payment processing starts', async () => {
    // Fill in payment form
    const cardNumberInput = page.getByLabel('Card Number');
    const expiryInput = page.getByLabel('Expiry Date');
    const cvvInput = page.getByLabel('CVV');
    const amountInput = page.getByLabel('Amount');

    await cardNumberInput.fill('4532015112830366');
    await expiryInput.fill('12/25');
    await cvvInput.fill('123');
    await amountInput.fill('99.99');

    // Click submit button
    const submitButton = page.getByRole('button', { name: /pay now/i });
    await submitButton.click();

    // Verify loading spinner appears
    const loadingSpinner = page.getByRole('status', { name: /processing/i });
    await expect(loadingSpinner).toBeVisible();

    // Verify submit button is disabled during processing
    await expect(submitButton).toBeDisabled();

    // Verify loading text is displayed
    const loadingText = page.getByText(/processing your payment/i);
    await expect(loadingText).toBeVisible();
  });

  test('should show loading state with progress indicator', async () => {
    // Fill payment form
    await page.getByLabel('Card Number').fill('4532015112830366');
    await page.getByLabel('Expiry Date').fill('12/25');
    await page.getByLabel('CVV').fill('123');
    await page.getByLabel('Amount').fill('150.00');

    // Submit payment
    await page.getByRole('button', { name: /pay now/i }).click();

    // Check for progress bar
    const progressBar = page.getByRole('progressbar');
    await expect(progressBar).toBeVisible();

    // Verify progress bar has aria-valuenow attribute
    await expect(progressBar).toHaveAttribute('aria-valuenow', /\d+/);

    // Verify loading message is present
    const loadingMessage = page.getByText(/please wait/i);
    await expect(loadingMessage).toBeVisible();
  });

  test('should hide loading state after payment completes successfully', async () => {
    // Fill and submit payment form
    await page.getByLabel('Card Number').fill('4532015112830366');
    await page.getByLabel('Expiry Date').fill('12/25');
    await page.getByLabel('CVV').fill('123');
    await page.getByLabel('Amount').fill('75.50');

    const submitButton = page.getByRole('button', { name: /pay now/i });
    await submitButton.click();

    // Verify loading state is visible
    const loadingSpinner = page.getByRole('status', { name: /processing/i });
    await expect(loadingSpinner).toBeVisible();

    // Wait for success message to appear
    const successMessage = page.getByText(/payment successful/i);
    await expect(successMessage).toBeVisible({ timeout: 10000 });

    // Verify loading spinner is hidden
    await expect(loadingSpinner).not.toBeVisible();

    // Verify submit button is re-enabled
    await expect(submitButton).toBeEnabled();
  });

  test('should display error state if payment processing fails', async () => {
    // Fill form with invalid card
    await page.getByLabel('Card Number').fill('4000000000000002');
    await page.getByLabel('Expiry Date').fill('12/25');
    await page.getByLabel('CVV').fill('123');
    await page.getByLabel('Amount').fill('50.00');

    const submitButton = page.getByRole('button', { name: /pay now/i });
    await submitButton.click();

    // Verify loading state appears
    const loadingSpinner = page.getByRole('status', { name: /processing/i });
    await expect(loadingSpinner).toBeVisible();

    // Wait for error message
    const errorMessage = page.getByText(/payment failed/i);
    await expect(errorMessage).toBeVisible({ timeout: 10000 });

    // Verify loading spinner is hidden
    await expect(loadingSpinner).not.toBeVisible();

    // Verify submit button is enabled again for retry
    await expect(submitButton).toBeEnabled();

    // Verify error details are shown
    const errorDetails = page.getByText(/invalid card/i);
    await expect(errorDetails).toBeVisible();
  });

  test('should prevent multiple submissions during loading state', async () => {
    // Fill payment form
    await page.getByLabel('Card Number').fill('4532015112830366');
    await page.getByLabel('Expiry Date').fill('12/25');
    await page.getByLabel('CVV').fill('123');
    await page.getByLabel('Amount').fill('99.99');

    const submitButton = page.getByRole('button', { name: /pay now/i });

    // Click submit button
    await submitButton.click();

    // Verify button is disabled
    await expect(submitButton).toBeDisabled();

    // Attempt to click disabled button (should not trigger another request)
    const clickPromise = submitButton.click().catch(() => {
      // Expected to fail since button is disabled
    });

    // Verify loading state is still visible
    const loadingSpinner = page.getByRole('status', { name: /processing/i });
    await expect(loadingSpinner).toBeVisible();

    // Wait for completion
    const successMessage = page.getByText(/payment successful|payment failed/i);
    await expect(successMessage).toBeVisible({ timeout: 10000 });
  });

  test('should display loading state with estimated time remaining', async () => {
    // Fill payment form
    await page.getByLabel('Card Number').fill('4532015112830366');
    await page.getByLabel('Expiry Date').fill('12/25');
    await page.getByLabel('CVV').fill('123');
    await page.getByLabel('Amount').fill('200.00');

    // Submit payment
    await page.getByRole('button', { name: /pay now/i }).click();

    // Verify loading state with time estimate
    const loadingSpinner = page.getByRole('status', { name: /processing/i });
    await expect(loadingSpinner).toBeVisible();

    // Check for estimated time text
    const timeEstimate = page.getByText(/estimated time|seconds remaining/i);
    await expect(timeEstimate).toBeVisible();

    // Verify time estimate updates or disappears when complete
    const completionMessage = page.getByText(/payment successful|payment failed/i);
    await expect(completionMessage).toBeVisible({ timeout: 10000 });

    // Verify time estimate is hidden after completion
    await expect(timeEstimate).not.toBeVisible();
  });
});
